function mostWeeklySales(sales) {
  let l = 0,
    r = 0;
  let windowSum = 0;
  let curMax = 0;
  while (r < sales.length) {
    windowSum += sales[r];
    r++;
    if (r - l === 7) {
      curMax = Math.max(curMax, windowSum);
      windowSum -= sales[l];
      l++;
    }
  }
  return curMax;
}

