class MostWeeklySales {
  public int solve(int[] sales) {
    int l = 0, r = 0;
    int windowSum = 0;
    int curMax = 0;
    while (r < sales.length) {
      windowSum += sales[r];
      r++;
      if (r - l == 7) {
        curMax = Math.max(curMax, windowSum);
        windowSum -= sales[l];
        l++;
      }
    }
    return curMax;
  }
}

